-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"تطور فنون النثر الحديث","passage":"يتنوع النثر الأدبي الحديث بين المقالة والقصة والمسرحية وأشكال أخرى مع تغير وسائل النشر والقراء، لكن إطلاق حكم تاريخي عن مرحلة يتطلب أمثلة مؤرخة. في نص مستقل يكتب طالب قصة ومقالًا عن الحدث ذاته للمقارنة بين السرد والحجاج.","prompt":"ما الذي يميز المقالة عن القصة في التدريب؟","correct":"مركزية الفكرة والحجة مقابل بناء الحدث","w1":"ذكر أسماء فقط","w2":"وجود ورق","w3":"طول العنوان","practice":"كوّن خريطة لأنواع النثر مع مثال موثق من كل نوع وأوجه تطور الشكل والمضمون."},{"n":2,"skill":"الأدب واليقظة القومية","passage":"يتناول بعض الأدب الحديث قضايا الهوية والمشاركة والإصلاح عبر سياقات مختلفة، فلا يصح اعتبار كل قصيدة حديثة بيانًا قوميًّا. المثال الأصلي يصف طالبة تقرأ تاريخ بلدها وتناقش أهمية خدمة المجتمع، ولا ينسب القول إلى مؤلف تاريخي.","prompt":"أي خطوة تثبت علاقة نص بقضية قومية؟","correct":"تحليل شاهد موثق وسياقه","w1":"الحكم من تاريخ الطباعة فقط","w2":"إضافة شعار","w3":"إلغاء المصدر","practice":"بعد توثيق نص أدبي حديث، اشرح قضية عامة يناقشها وشاهدًا واحدًا يدعم استنتاجك."},{"n":3,"skill":"الأدب والحياة الاجتماعية","passage":"يمكن أن تكشف القصة أو المقالة الأدبية تغير العادات والعمل والعلاقات بين الناس، لكن الراوي ليس بالضرورة شاهدًا تاريخيًا مباشرًا. نص تدريبي مستقل: اختلف جاران على استخدام ساحة مشتركة، ثم تفاوضا حول تنظيمها؛ يبرز موضوعًا اجتماعيًا.","prompt":"ما القضية الاجتماعية في النموذج؟","correct":"تنظيم الحق في استخدام مكان مشترك","w1":"وصف بحر شعري","w2":"سيرة شاعر","w3":"تاريخ معركة","practice":"قارن بين معالجة قضية اجتماعية في نص أصلي مؤرخ ومشهد من إنشائك، مع فصل الرأي من الحدث."},{"n":4,"skill":"الأدب وعلاقته بالسياسة","passage":"قد يعكس الأدب تجارب اجتماعية وسياسية وأصواتًا متعددة، ولا يجوز نسبة موقف سياسي لمؤلف من العنوان فقط. نموذج مستقل يحكي اجتماع مجلس طلابي يناقش توزيع الموارد ويعرض ثلاثة آراء مختلفة؛ ليس حدثًا تاريخيًا.","prompt":"ما الذي يجعل تحليل النص السياسي منصفًا؟","correct":"قراءة السياق وعرض الدليل والآراء ذات الصلة","w1":"نسبة كلام غير موجود","w2":"إلغاء اختلاف الأصوات","w3":"الاعتماد على الانطباع","practice":"وثق نصًا يناقش قضية عامة، واستخرج حجة ورأيًا مخالفًا وحدود الاستنتاج دون أحكام غير مسندة."},{"n":5,"skill":"الأجناس الشعرية الحديثة","passage":"تتغير البنية بين القصيدة العمودية وبعض أشكال الشعر الحر وقصيدة النثر، ويحتاج التصنيف إلى فحص الإيقاع والتقطيع والبناء لا مجرد طول السطر. في تدريب مستقل يُطلب النظر في مقطعين غير منسوبين واستخراج أثر التكرار.","prompt":"ما الأساس الصحيح لتصنيف شكل قصيدة؟","correct":"دراسة البنية والإيقاع والسياق","w1":"اسم الشاعر فقط","w2":"العنوان وحده","w3":"عدد الصفحات","practice":"قارن نصين موثقين من جنسين شعريين، ووضح البنية والتكرار والعلاقة بالمعنى."},{"n":6,"skill":"قراءة «قيود» دون اختلاق أبيات","passage":"يلزم نص «قيود» لعمر أبي ريشة بنسخته المدرسية لتحديد الرمز والمخاطَب وعاطفة الشاعر. مثال نثري مستقل: «وقف العامل أمام باب مغلق يشعر أن الخيارات تضيق»، يعرض صورة للقيد النفسي ولا يمثل بيتًا من القصيدة.","prompt":"ما الرمز المركزي في المثال المستقل؟","correct":"الباب المغلق والخيارات الضيقة","w1":"الفرح في حديقة","w2":"حوار المعلم","w3":"تعريف البحر","practice":"أبرز من القصيدة الأصلية موضعًا دالًا على القيد أو التحرر واشرح دلالته بشاهد موثق."},{"n":7,"skill":"القافية ومكوناتها وعيوبها","passage":"في علم العروض تُدرس القافية من آخر البيت إلى حدود صوتية محددة، وتشمل مصطلحات مثل الروي والوصل والردف مع أحكام لا تحددها الكلمة الأخيرة وحدها. يتطلب تحديد السناد والإقواء والإصراف مقارنة أبيات القصيدة الأصلية وضبطها.","prompt":"ما الحرف الأساس في نظام القافية المسمى الروي؟","correct":"الحرف الذي تبنى عليه قافية القصيدة","w1":"حرف الجر","w2":"همزة الوصل دائمًا","w3":"أول حرف في البيت","practice":"اختر أبياتًا موثقة من قصيدة واحدة، وحدد الروي وحروف القافية مع شرح احتمال عيب موثق إن وجد."},{"n":8,"skill":"النص الفكري وتحليل الحجة","passage":"عنوان «هذه بعض سماتنا» لزكي نجيب محمود لا يكفي لتعيين الفكرة التي يدافع عنها؛ يرجع التحليل إلى المقال الأصلي. تدريب مستقل: يدعي كاتب أن الحوار يحسن اتخاذ القرار ثم يشرح مثالًا لاجتماع فريق، ويحتاج تمييز الدعوى من الدليل.","prompt":"ما العنصر الذي يحول الرأي إلى حجة؟","correct":"تعليل مدعوم بمثال أو مصدر","w1":"تكرار العنوان","w2":"حذف الاعتراض","w3":"إطلاق حكم مطلق","practice":"اقرأ نص زكي نجيب محمود المقرر واستخرج دعوى واضحة ودليلًا أو مثالًا، ثم قيّم قوة الاستدلال."},{"n":9,"skill":"الصوت الوجداني في «وامعتصماه»","passage":"تحليل قصيدة «وامعتصماه» لإبراهيم العريض يحتاج المصدر الشعري نفسه لتحديد المخاطب والنداء والرواية التاريخية، ولا يجوز اختلاق رواية أو بيت ونسبته إلى الشاعر. مثال مستقل يطلب متحدث النجدة بصوت مرتفع؛ يمثل نداءً لا اقتباسًا.","prompt":"ما الوظيفة التي قد يؤديها النداء في عنوان القصيدة؟","correct":"استدعاء المخاطب وإبراز الانفعال بحسب النص","w1":"الجزم بالفعل فقط","w2":"المقارنة الرقمية","w3":"وصف مكان محايد","practice":"استخرج من القصيدة نداء موثقًا أو صورة وجدانية واشرح أثرها دون الخلط بين تاريخ الرواية والخيال."},{"n":10,"skill":"إعداد ترجمة أدبية للمازني","passage":"ترجمة إبراهيم المازني ينبغي أن تعتمد مراجع موثوقة للأسماء والآثار والسياقات، لا على سرد سيرة متخيلة. في نموذج تدريبي يبني الطالب بطاقة تضم الاسم والمرحلة الأدبية ومؤلفًا موثقًا ومقطعًا قصيرًا محل تحليل.","prompt":"ما الممارسة اللازمة في الترجمة الأدبية؟","correct":"ذكر عمل موثق ومصدره","w1":"إضافة قول مختلق","w2":"حذف التاريخ كله","w3":"تغيير اسم المؤلف","practice":"أنشئ بطاقة تعريف بالمازني مع مصدرين موثوقين وقائمة آثار صحيحة ثم ناقش ملمحًا أسلوبيًا بشاهد."},{"n":11,"skill":"الرسالة والتأمل في التجربة","passage":"نص «رسالة من تجاربي» لأحمد أمين يحتاج القراءة المقررة لتحديد تفاصيل الخبرة ومقصد الكاتب. مثال مستقل: «تعلم الطالب من إخفاق تجربة علمية ضرورة التحقق من القياس قبل الحكم»، وهو تدريب على التأمل لا نص من المؤلف.","prompt":"ما العبرة التي خلص إليها الطالب في المثال؟","correct":"التحقق من القياس قبل إصدار حكم","w1":"تجنب كل تجربة","w2":"رفض تصحيح الخطأ","w3":"إخفاء النتائج","practice":"استخرج من نص أحمد أمين تجربة موثقة ودليلًا على أثرها، ثم اكتب تأملًا شخصيًا يوضح التعلم."},{"n":12,"skill":"تطبيقات القافية والمراجعة","passage":"لتحليل قافية أبيات متعددة تُحدد كتابةً عروضية وتُستخرج حروف الروي وما يلحق بها مع مراعاة الوقف، ثم تقارن القوافي لتعرف الاتساق أو العيب. التدريب هنا لا يصنع أبياتًا على لسان الشعراء ولا يفترض صحة قصيدة مجهولة المصدر.","prompt":"ما أول إجراء في دراسة قافية قصيدة؟","correct":"الحصول على أبيات مضبوطة وموثقة","w1":"اختراع قافية","w2":"اختيار آخر حرف من العنوان","w3":"إلغاء التقطيع","practice":"اختر أربعة أبيات من قصيدة معروفة المصدر وحدد الروي والوصل والردف والتغيرات إن وجدت."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=12
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='79a8732d-6a86-46cd-8cad-31673af20a0c'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='أدب 312 — الأدب والنصوص' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثاني عشر، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثاني عشر%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G12_T2_ADAB312_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G12_T2_ADAB312_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G12_T2_ADAB312_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G12_T2_ADAB312_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;